 function draftValues(){if(!placeDraft||!editor.open)return;const form=editor.querySelector('#place-form');if(!form)return;const v=Object.fromEntries(new win.FormData(form));for(const key of ['name','country','city','district','address','note'])if(v[key]!==undefined)placeDraft[key]=v[key];placeDraft.links=[...form.querySelectorAll('[data-link-row]')].map(row=>({url:row.querySelector('[data-link-url]').value,label:row.querySelector('[data-link-label]').value}));}
