 function persistDrafts(){if(editor.open&&placeDraft&&(editSignature(editor)!==editBaselines.get(editor)||editor.dataset.draftRestored==='true')){draftValues();drafts.write('place',{place:placeDraft,editingId:editor.dataset.editing||null,query:editor.querySelector('#place-search-query')?.value||'',link:editor.querySelector('#place-google-link')?.value||''});}if(visitEditor.open&&visitDraft&&(editSignature(visitEditor)!==editBaselines.get(visitEditor)||visitEditor.dataset.draftRestored==='true')){const form=visitEditor.querySelector('form'),v=Object.fromEntries(new win.FormData(form));drafts.write('visit',{visit:{id:visitDraft.id,placeId:visitDraft.placeId,date:v.date,participants:[...form.querySelectorAll('[name=participants]:checked')].map(el=>el.value),rating:v.rating||'',revisit:v.revisit||'',review:v.review||'',photos:[...keptPhotos]},editingId:visitEditor.dataset.editing||null});}}
 function safePlaceDraft(value){const result={};for(const k of ['id','name','group','type','country','city','district','address','note'])if(typeof value?.[k]==='string')result[k]=value[k].slice(0,k==='note'||k==='address'?3000:200);for(const k of ['lat','lng'])if(Number.isFinite(value?.[k]))result[k]=value[k];if(Array.isArray(value?.links))result.links=value.links.slice(0,5).map(l=>({url:String(l?.url||'').slice(0,2048),label:String(l?.label||'').slice(0,100)}));if(!Object.hasOwn(placeTypes,result.group)||!placeTypes[result.group].includes(result.type)){result.group='美食';result.type='餐廳';}return result;}
 async function mountPositionPreview(){const target=editor.querySelector('#place-position-map');if(!target||!hasPlacePosition())return;try{const {L}=await ensureStreetAssets();if(!target.isConnected||!editor.open)return;if(!L){target.textContent='位置已取得，可繼續填寫。';return;}const point=[placeDraft.lat,placeDraft.lng];if(positionMap&&positionMap.getContainer()===target){positionMap.setView(point,16);positionPin.setLatLng(point);return;}positionMap?.remove();positionMap=L.map(target,{scrollWheelZoom:false}).setView(point,16);L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png',{attribution:'© OpenStreetMap contributors © CARTO',maxZoom:19}).addTo(positionMap);positionPin=L.marker(point).addTo(positionMap);positionMap.on('click',e=>{void selectCoordinates(e.latlng.lat,e.latlng.lng).then(persistDrafts).catch(error=>fail(editor,error));});}catch{if(target.isConnected)target.textContent='預覽地圖暫時無法載入，位置仍保留，可以繼續儲存。';}}
 function hasPlacePosition(){return Number.isFinite(placeDraft?.lat)&&Number.isFinite(placeDraft?.lng)&&Math.abs(placeDraft.lat)<=90&&Math.abs(placeDraft.lng)<=180;}
 function searchMarkup(value=''){return `<label class="place-search-label" for="place-search-query">先找地點：店名、地址或 Google 地圖連結</label><div class="place-search-line"><input id="place-search-query" aria-label="搜尋店名、地址或貼上Google地圖連結" placeholder="例如：新莊咖啡廳，或貼上地圖連結" value="${esc(value)}">${button('搜尋','data-place-search','primary')}</div><p class="hint">搜尋後選一個結果，位置與所在地會自動帶入。</p><div id="place-search-results"></div>`;}
