 async function selectCoordinates(lat,lng,extra={}){if(!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180){toast('這個位置不正確，請重新選擇');return;}if(!placeDraft||!selecting&&!editor.open)await openPlace(null);draftValues();if(!placeDraft)return;const generation=editGeneration,scope=getHomeId()+':'+getMember().userId;if(!editor.open)editor.showModal();placeDraft.lat=lat;placeDraft.lng=lng;if(map&&assets?.L){if(draftPin)map.removeLayer(draftPin);draftPin=assets.L.marker([lat,lng],{icon:assets.L.divIcon({className:'place-marker',html:'<span class="place-map-pin wish">'+icon('places')+'</span>',iconSize:[30,36],iconAnchor:[15,34]})}).addTo(map);}if(extra.name)placeDraft.name=extra.name;let location=assets?.geo.locateTaiwanDistrict(lat,lng);if(!location){try{location=extra.country&&extra.city&&(extra.district||!isTaiwan(extra.country))?extra:await search.reverse(lat,lng);}catch(e){toast('已取得位置，所在地暫時查不到；已填的資料會保留，請確認後再儲存。');location={country:placeDraft.city||!isTaiwan(placeDraft.country)?placeDraft.country:'',city:placeDraft.city||'',district:placeDraft.district||''};}}if(generation!==editGeneration||scope!==getHomeId()+':'+getMember().userId||!editor.open)return;Object.assign(placeDraft,location,extra.name?{name:extra.name}:{});if(isTaiwan(placeDraft.country)&&!assets?.geo.locateTaiwanDistrict(lat,lng))Object.assign(placeDraft,{country:'台灣',city:normalizeRegion(placeDraft.city),district:normalizeRegion(placeDraft.district)});editor.querySelector('[name=lat]').value=lat;editor.querySelector('[name=lng]').value=lng;editor.querySelector('[name=name]').value=placeDraft.name;editor.querySelector('#place-location-fields').innerHTML=locationFields(placeDraft);editor.querySelector('[name=address]').value=placeDraft.address||extra.address||'';updatePlacePosition();editor.querySelector('#place-form [role=alert]').textContent='';selecting=false;if(!editor.open)editor.showModal();persistDrafts();}
 const revisitLabels={yes:'😍 一定再來',maybe:'🙂 有機會再來',no:'🙅 不會再來'};
