 function openCard(id){const p=getData().places?.find(p=>p.id===id);if(!p){toast('地點已被刪除');return;}activeId=id;const s=placeSummary(getData(),id);show(card,`<h3>${esc(p.name)}</h3><p>${esc(p.group)} · ${esc(p.type)} · ${esc(p.country+'／'+p.city+'／'+p.district)}</p>${p.address?`<p>${esc(p.address)}</p>`:''}<div class="place-link-list">${p.links.map(l=>`<a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.label||'查看連結')}</a>`).join('')}</div><p class="place-shared-note">${esc(p.note||'')}</p>${s.count?`<p>第一次去：${esc(formatDate(s.first))} · 去過 ${s.count} 次</p>${s.members.map(r=>`<p>${dot(r.member.userId)}${esc(r.member.name)} · ${r.average===null?'還沒有評分':'平均 '+r.average.toFixed(1)+' ★'}${r.revisit?' · '+revisitLabels[r.revisit]:''}${r.waiting?' · 等 '+esc(r.member.name)+' 評分':''}</p>`).join('')}`:'<p class="hint">先放在願望清單，找一天一起去。</p>'}${button(s.count?'再記一次':'我們去了！',`data-place-new-visit="${esc(id)}"`,'primary')}${gallery(s.photos)}<div class="place-visits">${s.visits.map(v=>`<button class="record-item" data-place-edit-visit="${esc(v.id)}"><strong>${esc(formatDate(v.date))} · ${v.participants.map(uid=>esc(getData().members.find(m=>m.userId===uid)?.name||'未知成員')).join('、')}</strong><small>${v.participants.map(uid=>v.ratings[uid]===undefined?'等 '+esc(getData().members.find(m=>m.userId===uid)?.name||'成員')+' 評分':esc(getData().members.find(m=>m.userId===uid)?.name||'成員')+' '+v.ratings[uid]+'★').join(' · ')}</small><span>${esc(v.review||'')}</span></button>`).join('')}</div><div class="places-card-actions">${button('編輯地點',`data-place-edit="${esc(id)}"`)}${button('刪除地點',`data-place-delete="${esc(id)}"`,'edit-delete')}</div>`);void mountPhotos();}
 function openVisit(placeId,id=null){const saved=drafts.read('visit'),resumed=saved?.visit?.placeId===placeId&&saved.editingId===(id||null)?saved.visit:null;const p=getData().places?.find(p=>p.id===placeId),old=id?getData().placeVisits?.find(v=>v.id===id):null;if(!p||id&&!old){toast('地點或造訪已被刪除');return;}visitDraft=old?structuredClone(old):{id:win.crypto.randomUUID(),placeId,date:today(),participants:(getData().members||[]).map(m=>m.userId),ratings:{},revisit:{},review:'',photos:[]};keptPhotos=[...visitDraft.photos];const me=getMember();visitEditor.dataset.editing=id||'';show(visitEditor,`<form id="place-visit-form"><input type="hidden" name="photoPaths" value="${esc(JSON.stringify(keptPhotos))}"><h3>${esc(p.name)}</h3>${input('date','造訪日期',visitDraft.date,'date',true)}<p class="hint">請選造訪當地的日期，儲存後不會因時差自動換日。</p><fieldset><legend>這次有誰去</legend>${(getData().members||[]).map(m=>`<label><input type="checkbox" name="participants" value="${esc(m.userId)}" ${visitDraft.participants.includes(m.userId)?'checked':''}>${dot(m.userId)}${esc(m.name)}</label>`).join('')}</fieldset><div class="place-my-opinion"><label class="field">我的評分<select name="rating"><option value="">先不評分</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${visitDraft.ratings[me.userId]===n?'selected':''}>${'★'.repeat(n)}</option>`).join('')}</select></label><label class="field">我的再訪意願<select name="revisit"><option value="">先不決定</option>${Object.entries(revisitLabels).map(([value,label])=>`<option value="${value}" ${visitDraft.revisit[me.userId]===value?'selected':''}>${label}</option>`).join('')}</select></label><p class="hint">只能填自己的評分；對方可以打開這筆紀錄補上。</p></div><label class="field">一起寫的評論<textarea name="review" maxlength="500">${esc(visitDraft.review||'')}</textarea></label><div id="place-kept-photos"></div><label class="field">照片（最多 9 張）<input name="photos" type="file" accept="image/*" multiple></label><p role="alert"></p><div class="sheet-actions">${id?button('刪除造訪',`data-place-delete-visit="${esc(id)}"`,'edit-delete'):button('關閉','data-place-close')}<button class="primary" type="submit">儲存造訪</button></div></form>`);paintKept();updateOpinion();markEditorClean(visitEditor);if(resumed){visitEditor.dataset.draftRestored='true';const form=visitEditor.querySelector('form');form.querySelector('[name=date]').value=String(resumed.date||visitDraft.date);form.querySelector('[name=review]').value=String(resumed.review||'').slice(0,500);for(const el of form.querySelectorAll('[name=participants]'))el.checked=Array.isArray(resumed.participants)&&resumed.participants.includes(el.value);form.querySelector('[name=rating]').value=String(resumed.rating||'');form.querySelector('[name=revisit]').value=String(resumed.revisit||'');if(Array.isArray(resumed.photos))keptPhotos=resumed.photos.filter(p=>typeof p==='string'&&!p.includes('..')&&!p.startsWith('/')&&!/^https?:/i.test(p)).slice(0,9);paintKept();updateOpinion();form.insertAdjacentHTML('afterbegin','<p class="place-draft-restored" role="status">已接回文字與已上傳照片；未上傳的照片請重新選取。</p>');}}
 function paintKept(){visitEditor.querySelector('[name=photoPaths]').value=JSON.stringify(keptPhotos);visitEditor.querySelector('#place-kept-photos').innerHTML=keptPhotos.map((path,i)=>`<span class="place-kept-photo">照片 ${i+1}${button('×',`data-place-remove-photo="${i}" aria-label="移除照片${i+1}"`)}</span>`).join('');}
 function updateOpinion(){const mine=[...visitEditor.querySelectorAll('[name=participants]:checked')].some(input=>input.value===getMember().userId);for(const field of visitEditor.querySelectorAll('[name=rating],[name=revisit]')){field.disabled=!mine;if(!mine)field.value='';}}
 async function savePlaceForm(form){draftValues();if(!hasPlacePosition()){form.querySelector('[role=alert]').textContent='還沒選位置，請先搜尋地點或貼上 Google 地圖連結，再選擇正確的位置。';updatePlacePosition();showPlaceSearch();return;}const current=structuredClone(placeDraft),id=editor.dataset.editing,actor=getMember().userId,homeId=getHomeId(),at=new Date().toISOString();current.links=current.links.filter(l=>l.url.trim()).map(l=>({url:l.url.trim(),label:l.label.trim()}));current.name=current.name.trim();current.country=isTaiwan(current.country)?'台灣':current.country.trim();if(isTaiwan(current.country)){current.city=normalizeRegion(current.city);current.district=normalizeRegion(current.district);if(!assets?.geo.cities[current.city]?.includes(current.district))throw Error('請從清單選擇台灣縣市與區域');}Object.assign(current,{createdBy:current.createdBy||actor,createdAt:current.createdAt||at});validatePlace(current);const duplicate=duplicatePlace(getData(),current);if(duplicate){if(win.confirm('好像已經有這個地點了，要前往「'+duplicate.name+'」嗎？')){editor.close();openCard(duplicate.id);}return;}const ok=await mutate(()=>{if(getMember().userId!==actor||getHomeId()!==homeId)throw Error('家庭或登入狀態已改變，請重新開啟表單');const d=getData(),latest=d.places.find(p=>p.id===current.id);if(id&&!latest)throw Error('地點已被刪除');const other=duplicatePlace(d,current);if(other)throw Error('好像已經有這個地點了，請先查看「'+other.name+'」');savePlace(d,{...current,createdBy:latest?.createdBy||actor,createdAt:latest?.createdAt||at},{editing:Boolean(id)});},{onError:error=>fail(editor,error)});if(ok){editGeneration++;drafts.clear('place');if(!isTaiwan(current.country)){section='overseas';foreignCountry=overseasCountry(current.country);foreignCity=overseasCityKey(current);mode='map';render();}editor.close();openCard(current.id);toast('把這個地方記好了');}}
 async function saveVisitForm(form){const actor=getMember().userId,homeId=getHomeId(),id=visitEditor.dataset.editing,base=structuredClone(visitDraft),v=Object.fromEntries(new win.FormData(form)),participants=[...form.querySelectorAll('[name=participants]:checked')].map(input=>input.value),files=[...form.querySelector('[name=photos]').files];if(files.length+keptPhotos.length>9)throw Error('照片最多 9 張');if(!participants.length)throw Error('至少選一位參與成員');const paths=await photos.upload(files,base.placeId),savedPhotos=[...keptPhotos,...paths];keptPhotos=savedPhotos;form.querySelector('[name=photos]').value='';paintKept();persistDrafts();let unlocked=[];const at=new Date().toISOString();const ok=await mutate(()=>{if(getMember().userId!==actor||getHomeId()!==homeId)throw Error('家庭或登入狀態已改變，請重新開啟表單');const data=getData(),latest=data.placeVisits.find(record=>record.id===base.id);if(id&&!latest)throw Error('造訪已被刪除');const before=structuredClone(data),record={...(latest||base),date:v.date,participants,ratings:{...(latest?.ratings||{})},revisit:{...(latest?.revisit||{})},review:v.review||'',photos:savedPhotos,createdBy:latest?.createdBy||actor,createdAt:latest?.createdAt||at};for(const key of ['ratings','revisit'])delete record[key][actor];if(participants.includes(actor)){if(v.rating)record.ratings[actor]=Number(v.rating);if(v.revisit)record.revisit[actor]=v.revisit;}validatePlaceVisit(data,record);savePlaceVisit(data,record,actor,{editing:Boolean(id)});unlocked=newlyUnlocked(before,data);},{onError:error=>fail(visitEditor,error)});if(ok){drafts.clear('visit');visitEditor.close();openCard(base.placeId);if(unlocked.length){const text='🎉 解鎖新區域：'+unlocked.map(r=>isTaiwan(r.country)?r.city+r.district:r.country+'・'+r.city).join('、');if(celebrate)celebrate(text);else{const element=doc.createElement('div');element.className='places-celebration';element.textContent=text;element.setAttribute('role','status');doc.body.append(element);win.setTimeout(()=>element.remove(),3000);}}else toast('這次的小日子記好了');}}
 async function fetchLink(value){const generation=editGeneration,scope=getHomeId()+':'+getMember().userId;const url=(value??editor.querySelector('#place-google-link').value).trim();if(searchBusy)return;searchBusy=true;try{const token=await getAccessToken(),response=await fetchImpl('/api/place-from-link',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify({url}),signal:AbortSignal.timeout(14000)}),result=await response.json();if(generation!==editGeneration||scope!==getHomeId()+':'+getMember().userId||!editor.open)return;if(!response.ok)throw Error(result.error||'無法解析連結，請改用其他新增方式');await selectCoordinates(result.lat,result.lng,{name:result.name});draftValues();if(placeDraft.links.length<5&&!placeDraft.links.some(link=>link.url===url)){placeDraft.links.push({url,label:'Google 地圖'});paintLinks();}}catch(e){fail(editor,Error(e.name==='TimeoutError'?'連結解析逾時，仍可用地圖或目前位置新增':e.message));}finally{searchBusy=false;}}
 let results=[];
 doc.addEventListener('submit',async e=>{if(e.target.id==='place-city-form'){e.preventDefault();if(saving)return;const form=e.target,v=Object.fromEntries(new win.FormData(form)),country=foreignCountry,actor=getMember().userId,home=getHomeId(),count=getData().places.filter(p=>!isTaiwan(p.country)&&sameOverseasCountry(p.country,country)&&p.city===v.source).length;if(!v.target.trim()||v.target.trim()===v.source){fail(cityEditor,Error('請填入要統一的不同城市名稱'));return;}if(!win.confirm(`將 ${count} 個地點的城市「${v.source}」統一成「${v.target}」？`))return;saving=true;try{const ok=await mutate(()=>{if(getMember().userId!==actor||getHomeId()!==home)throw Error('家庭或登入狀態已改變');renameOverseasCity(getData(),country,v.source,v.target);},{summary:'整理海外城市：'+v.source+' → '+v.target});if(ok){foreignCity='';cityEditor.close();render();toast('城市名稱整理好了');}}catch(error){fail(cityEditor,error);}finally{saving=false;}return;}if(!['place-form','place-visit-form'].includes(e.target.id))return;e.preventDefault();if(saving)return;saving=true;const submit=e.target.querySelector('[type=submit]');submit.disabled=true;try{if(e.target.id==='place-form')await savePlaceForm(e.target);else await saveVisitForm(e.target);}catch(error){fail(e.target.closest('dialog'),error);}finally{saving=false;submit.disabled=false;}});
 doc.addEventListener('input',e=>{if(e.target.closest('#places-editor,#place-visit-editor'))persistDrafts();});
